    if (argc > 1) {
        N = std::atoi(argv[1]);
    }

    std::string line;
    std::string seq;
    bool in_three = false;

    while (std::getline(std::cin, line)) {
        // Remove trailing carriage return if present
        if (!line.empty() && line.back() == '\r') {
            line.pop_back();
        }
        if (line.empty()) continue;

        if (line[0] == '>') {
            if (line.find("THREE") != std::string::npos) {
                in_three = true;
            } else {
                in_three = false;
            }
        } else if (in_three) {
            seq += line;
        }
    }

    // Normalize to upper case
    for (char &c : seq) {
        c = std::toupper(static_cast<unsigned char>(c));
    }

    // Count 1-mers
    std::map<char, int> count1;
    for (char c : seq) {
        if (c == 'A' || c == 'C' || c == 'G' || c == 'T') {
            count1[c]++;
        }
    }

    // Count 2-mers
    std::map<std::string, int> count2;
    for (size_t i = 0; i + 1 < seq.size(); ++i) {
        std::string kmer = seq.substr(i, 2);
        if ((kmer[0] == 'A' || kmer[0] == 'C' || kmer[0] == 'G' || kmer[0] == 'T') &&
            (kmer[1] == 'A' || kmer[1] == 'C' || kmer[1] == 'G' || kmer[1] == 'T')) {
            count2[kmer]++;
        }
    }

    // Sort 1-mers
    std::vector<std::pair<char, int>> vec1(count1.begin(), count1.end());
    std::sort(vec1.begin(), vec1.end(), [](const std::pair<char, int>& a, const std::pair<char, int>& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    // Sort 2-mers
    std::vector<std::pair<std::string, int>> vec2(count2.begin(), count2.end());
    std::sort(vec2.begin(), vec2.end(), [](const std::pair<std::string, int>& a, const std::pair<std::string, int>& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    // Output 1-mers
    for (const auto& p : vec1) {
        std::cout << p.second << '\t' << p.first << '\n';
    }

    // Output 2-mers
    for (const auto& p : vec2) {
        std::cout << p.second << '\t' << p.first << '\n';
    }

    // Specific fragments
    const std::vector<std::string> fragments = {
        "GGT", "GGTA", "GGTATT", "GGTATTTTAATT", "GGTATTTTAATTTATAGT"
    };
    for (const auto& frag : fragments) {
        int count = 0;
        size_t pos = seq.find(frag, 0);
        while (pos != std::string::npos) {
            count++;
            pos = seq.find(frag, pos + 1);
        }
        std::cout << count << '\t' << frag << '\n';
    }

    return 0;
}
