#include <cstdio>
#include <cstdlib>

struct Tree {
    Tree* left;
    Tree* right;
};

static Tree* free_list = nullptr;

void* alloc_block(size_t count) {
    // allocate a block of Tree nodes
    Tree* block = (Tree*)std::malloc(count * sizeof(Tree));
    if (!block) std::abort();
    // thread into free list
    for (size_t i = 0; i < count; ++i) {
        block[i].left = free_list;
        free_list = &block[i];
    }
    return block;
}

Tree* alloc_node() {
    if (!free_list) {
        // allocate 1<<20 nodes
        alloc_block(1 << 20);
    }
    Tree* node = free_list;
    free_list = free_list->left;
    return node;
}

void free_node(Tree* node) {
    node->left = free_list;
    free_list = node;
}

Tree* new_tree(int depth) {
    Tree* t = alloc_node();
    if (depth > 0) {
        t->left = new_tree(depth - 1);
        t->right = new_tree(depth - 1);
    } else {
        t->left = nullptr;
        t->right = nullptr;
    }
    return t;
}

int check_tree(const Tree* t) {
    if (t->left == nullptr) return 1;
    return 1 + check_tree(t->left) + check_tree(t->right);
}

void delete_tree(Tree* t) {
    if (t->left) {
        delete_tree(t->left);
        delete_tree(t->right);
    }
    free_node(t);
}

